				break
			}
			if _, err = conn.ExecContext(ctx, `INSERT OR IGNORE INTO enrollments(id,tenant_id,course_id,learner_id,enrolled_at_utc,completed_at_utc) VALUES(?,?,?,?,?,?)`, enrollment, tenant, course, learner, utc, utc); err != nil {
				break
			}
