			}
		}
		if err != nil {
			conn.ExecContext(ctx, "ROLLBACK")
			conn.Close()
			return err
		}
		_, err = conn.ExecContext(ctx, "COMMIT")
		conn.Close()
		if err != nil {
			return err
		}
	}
	return nil
}
